  (* [comment removed for export] *)
  Ltac disjL LV := try (destruct LV as [LV|LV]; [| disjL LV]).
  (* [comment removed for export] *)
  Ltac splitsL Hx := let c := constr:(Hx) in nd_splits c.   (* [comment removed for export] *)
  (* [comment removed for export] *)
  Ltac leafx P :=
    let pc1 := fresh "pc" in let r1 := fresh "r" in let m1 := fresh "m" in let E := fresh "E" in let LV := fresh "LV" in
    destruct P as (pc1 & r1 & m1 & E & LV); subst; disjL LV; splitsL LV; subst pc1; try subst m1.
  (* [comment removed for export] *)
  Ltac chase := repeat match goal with E : _ = _ |- _ => progress (rewrite E) end.
  Ltac eqt := first [ eassumption | reflexivity | etransitivity; [eassumption| eqt] ].
