  Lemma lit_m2049b : ltac2:(zQ "40!h9!nd!lb!jc@3$2@1$3@1$0#k0@2$1@1$0#k0-og1@2$1@1$0#k0+vvvvvvvvvvvvvnvf").
Proof.
ltac2:(KReplay.run1z (kr_t_W_bpesc4c ()) ["HCW"] "##'>h02b1h12b2h21nh31Hp;1p;3p;2g005=j13Tg009Mj35Tg00HSj22Tg01_Nj39Tg004_j1<!s/$:j10Tg00X;j1;Tg008gj28Tg003Uj16!s8$Ij1:Tg00ocj2=Tf0R0#6#6p=4%00#0p=7!s-$!s$/p=1g02QnR1%30R2f1R3#3R4g00eff2R5#3?530g025[R6f3R7/25127335R8[12531250556%37?553[R9f4#3?575\8A9530P0n20010!s#$12!s-%0W1W0W2P9^14^02^21P0g02G3R0#4#4#4R1#<R2%41#4#0#;,82%00#7#1!s$-6#!s8%:,82R01220,=6O4b3o"). Qed.
  Ltac pecore_tac := unfold pecore; repeat apply conj; first [ eqt | (etransitivity; [eqt| first [apply lit_m2049b | symmetry; apply lit_m2049b]]) ].
  (* [comment removed for export] *)
  Ltac solve_prem := first [ eassumption | reflexivity | pecore_tac | (chase; first [eassumption | reflexivity | lia])
                           | (symmetry; apply Z_to_bv_bv_unsigned) | lia ].
  Ltac run_seg L := hide_post_once; eapply evt_cut; [eapply L; solve_prem|]; let ms := fresh "ms" in let P := fresh "P" in intros ms P; leafx P.   (* [comment removed for export] *)
  (* [comment removed for export] *)
  Ltac is_areg f := lazymatch f with ra0 => idtac | ra1 => idtac | ra2 => idtac | ra3 => idtac | ra4 => idtac | ra5 => idtac | ra6 => idtac | ra7 => idtac end.
  Ltac prune_for_lia := repeat match goal with
    | H : rw_cells _ _ _ _ |- _ => clear H
    | H : ro_cells _ _ _ _ |- _ => clear H
    | H : peframe _ _ _ _ _ _ _ _ _ |- _ => clear H
    | H : pecells _ _ _ _ _ _ |- _ => clear H
    | H : petot _ _ _ |- _ => clear H
    | H : pesize _ _ _ |- _ => clear H
    | H : pinb _ _ _ _ |- _ => clear H
    | H : pshb _ _ _ |- _ => clear H
    | H : ptsh _ _ |- _ => clear H
    | H : mem_inv _ _ |- _ => clear H
    | H : pectx _ _ _ _ _ _ _ _ _ |- _ => clear H
    | H : pecore _ _ _ _ _ |- _ => clear H
    | E : ?f ?rk = _ |- _ => lazymatch type of rk with rv => tryif is_areg f then fail else clear E end
    end.
  Ltac chase_all := repeat match goal with E : ?f ?rk = _ |- _ => is_areg f; lazymatch type of rk with rv => progress (rewrite E in * ) end end.
  Ltac leaf_atom := first [ eassumption | reflexivity | eqt
    | lazymatch goal with
      | |- @eq _ _ _ => fail
      | |- _ => first [lia | (prune_for_lia; chase_all; rewrite ?unsigned_lit by lia; lia)] end ].
  Ltac leaf_conj := first [ nsplit; leaf_atom | repeat (split; [leaf_atom|]); leaf_atom ].   (* [comment removed for export] *)
  (* [comment removed for export] *)
  Ltac solve_leaf_stock := lazymatch goal with
    | |- (?a = ?a /\ _) \/ _ => first [ left; leaf_conj | right; solve_leaf_stock ]
    | |- (_ = _ /\ _) \/ _ => right; solve_leaf_stock
    | |- _ => leaf_conj end.
  (* [comment removed for export] *)
  Ltac solve_leaf_n l i rest :=
    lazymatch rest with
    | @cons _ ?A (@nil _) => refine (@or_chainI l i A (@eq_refl (option Prop) (@Some Prop A)) _); leaf_conj
    | @cons _ ?A ?rest2 =>
        lazymatch A with
        | (?a = ?a /\ _) => first [ refine (@or_chainI l i A (@eq_refl (option Prop) (@Some Prop A)) _); leaf_conj | solve_leaf_n l (S i) rest2 ]
        | (_ = _ /\ _) => solve_leaf_n l (S i) rest2
        end
    end.
  Ltac solve_leaf := lazymatch goal with
    | |- _ \/ _ => first [ (let g := lazymatch goal with |- ?g => g end in let l := or_spine_list g in solve_leaf_n l O l) | solve_leaf_stock ]
    | |- _ => leaf_conj end.
  Ltac close_leaves :=
    apply evt_done; unhide_post;   (* [comment removed for export] *)
    lazymatch goal with |- seg_post _ _ _ (MS (mkRr ?rx) _ (Z_to_bv 64 ?pcv) _ _ ?mm _) => nexists pcv, rx, mm; split; [reflexivity|] end;
